 Face.prototype.defaults = {

	"boundTo"		: "body"		,
	"face_width"	: 1000		,
	"face_height"	: 1000		,
	"gaze"	: {
			"x"			: 0.5 ,
			"y"			: 0.5
	},
	"expressionTransitions" : {

			"duration"		: 500
	}

 };





 Face.prototype._init 						= function()
 {
	var 	face 						=	this								,
			expressions 			=	face.settings.expressions ,
			v 							=	0									,
			newExpr															,
			newCanvas														;

			face.current.gaze.x	=  face.settings.gaze.x		;
			face.current.gaze.y	=  face.settings.gaze.y		;



			if( !face.canvas )
			{

					if( !document.getElementById( "face-canvas" ) )
					{

							newCanvas = document.createElement( "canvas" );
							newCanvas.setAttribute( "id"		, "face-canvas" 					);
							newCanvas.setAttribute( "width"	, face.settings.face_width  	);
							newCanvas.setAttribute( "height"	, face.settings.face_height 	);

							document.querySelector( face.settings.boundTo ).appendChild( newCanvas );

							face.canvas = new fabric.StaticCanvas(	newCanvas	 , { renderOnAddRemove: false , stateful: false , selection : false });

					}else
					{
							document.getElementById( "face-canvas" ).setAttribute( "width"	, face.settings.face_width  	);
							document.getElementById( "face-canvas" ).setAttribute( "height"	, face.settings.face_height 	);
							face.canvas = new fabric.StaticCanvas(	'face-canvas'	 , { renderOnAddRemove	: false , stateful	: false , selection : false  } );
					}

			}


 };



 Face.prototype._destroy  				= function()
 {
	var 	face 	= 	this ,
			canv = document.getElementById( "face-canvas" );

			if( face.canvas )
			{
				face.canvas.dispose();
			}
			if( canv )
			{
				canv.parentNode.removeChild( canv );
			}
			this.expressions 	= 	null;
			this.synonyms	=	null;
			this.settings		=	null;
			this.loadingComponents	= null;
			this.canvas			=	null;
			this._tttt 			= 	null;
 };


 Face.prototype._createExpression 	= function( expressionParams )
 {
	var	face		=	this,
			exists	=	this._getExpression( expressionParams.name ),
			inherits;

			if( exists )
			{
						if( face.current.expression === exists.name ){ face.current.expression = "" ;}
						exists.destroy();
						inherits		=	{
										"_Face" 			: face
						};
						return	new Expression(	inherits	,	expressionParams );
			}else
			{
						inherits		=	{
										"_Face" 			: face
						};
						return	new Expression(	inherits	,	expressionParams );
			}

 };

  Face.prototype._addExpression 	= function( Expression )
 {
	var	face		=	this;
			face.expressions.push( 	Expression 	);

 };

 Face.prototype._parseExpressions 	= function( callback  )
 {
			if( !callback ){ return false; }

	var	exprs = 	this.expressions ,
			len	=	exprs.length,
			m		=	0,
			cal	= null;

			for(	var m = exprs.length - 1; m >= 0; m-- )
			{
					cal = callback( exprs[ m ] , m );
					if( cal	===	false ){	break;	}
			}
			return cal;
 };



 Face.prototype._getExpression 	= function( expressionName )
 {
			var	face	= 	this;
			var	eexx	=	false;


			for( var z = 0; z < face.synonyms.length; z++ )
			{
					for( var r = 0; r < face.synonyms[ z ].expressionSynonyms.length; r++ )
					{
							if( expressionName === face.synonyms[ z ].expressionSynonyms[ r ] )
							{
											expressionName	=	face.synonyms[ z ].expressionName ;
							}
					}
			}



									this._parseExpressions(
															function( expr )
															{
																					if( expr.name === expressionName ){	eexx	=	expr; return false;}
															}
									);

			return eexx;

 };





  Face.prototype._switchExpression 	= function( nextExpression )
 {

	var	face						= this;
	var   dur 						= face.settings.expressionTransitions.duration,dure;
	var	prepareToAnimate 	= [];

	var	nextExprObj 			= face._getExpression( nextExpression );
	var	currentExprObj 		= face._getExpression( face.current.expression );

			if(  currentExprObj  )
			{

					for( var m  = 0; m < currentExprObj.expressionElements.length; m++ )
					{
							if( currentExprObj.expressionElements[ m ].name === "background" )
							{
									currentExprObj.expressionElements[ m ].to_params.opacity = 1 ;
									face.canvas.sendToBack(	currentExprObj.expressionElements[ m ].UI_elem	);
							}
							else
							{
									currentExprObj.expressionElements[ m ].to_params.opacity = 0 ;
									face.canvas.bringToFront(	currentExprObj.expressionElements[ m ].UI_elem	);
							}



							currentExprObj.expressionElements[ m ].to_params.left 		= currentExprObj.expressionElements[ m ].params.left 		;
							currentExprObj.expressionElements[ m ].to_params.top 		= currentExprObj.expressionElements[ m ].params.top 		;
							currentExprObj.expressionElements[ m ].to_params.width 	= currentExprObj.expressionElements[ m ].params.width 	;
							currentExprObj.expressionElements[ m ].to_params.height 	= currentExprObj.expressionElements[ m ].params.height	;
					}

			}

			for( var m  = 0; m < nextExprObj.expressionElements.length; m++ )
			{
					nextExprObj.expressionElements[ m ].params.opacity = 0;
					nextExprObj.expressionElements[ m ].draw( face.canvas );
					nextExprObj.expressionElements[ m ].params.opacity = 1;

							if( nextExprObj.expressionElements[ m ].name === "background" )
							{
									face.canvas.bringToFront(	nextExprObj.expressionElements[ m ].UI_elem	);
							}else
							{
									face.canvas.bringToFront(	nextExprObj.expressionElements[ m ].UI_elem	);
							}

					if(  currentExprObj  ){

							var	sameElement = currentExprObj.getExpressionElement(  nextExprObj.expressionElements[ m ].name  );
							if( sameElement	)
							{

								sameElement.to_params.left 		= nextExprObj.expressionElements[ m ].params.left 		;
								sameElement.to_params.top 		= nextExprObj.expressionElements[ m ].params.top 		;
								sameElement.to_params.width 		= nextExprObj.expressionElements[ m ].params.width 	;
								sameElement.to_params.height 	= nextExprObj.expressionElements[ m ].params.height	;


								nextExprObj.expressionElements[ m ].UI_elem.left			=	sameElement.UI_elem.left;
								nextExprObj.expressionElements[ m ].UI_elem.top			=	sameElement.UI_elem.top;
								nextExprObj.expressionElements[ m ].UI_elem.width		=	sameElement.UI_elem.width;
								nextExprObj.expressionElements[ m ].UI_elem.height		=	sameElement.UI_elem.height;
								nextExprObj.expressionElements[ m ].UI_elem.setCoords();

							}
					}
			}
			face._stopAllAnimate();


			if(  nextExprObj  && nextExprObj.expressionElements.length > 0 )
			{

					nextExprObj.parseExpressionElements(
																	function(el , indexKey )
																	{
																		if( el )
																		{
																				duration = face.settings.expressionTransitions.duration ;
																				face.transitionIsRunning = true;
																				el.animate("GoToDefault" , null , null , null , { duration : duration	, onComplete : function(){face.transitionIsRunning = false;}		});
																		}
																	}
																);
			}
			if(  currentExprObj && currentExprObj.expressionElements.length > 0  )
			{

					currentExprObj.parseExpressionElements(
																				function( el , indexKey )
																				{
																					if( el ){
																									el.animate("GoToTarget" , el.to_params	  , null , null , {
																																	duration 		: face.settings.expressionTransitions.duration ,
																																	onComplete 	: function()
																																	{
																																			el.UI_elem.left		=	el.params.left;
																																			el.UI_elem.top		=	el.params.top;
																																			el.UI_elem.width		=	el.params.width;
																																			el.UI_elem.height	=	el.params.height;
																																			el.UI_elem.setCoords();
																																			el.clear();
																																	}
																																});
																					}
																				}
																			);
			}



 };


 Face.prototype._switchGaze 	= function()
 {

	var	face							= this;
	var	currentExprObj 			= face._getExpression( face.current.expression );

			face._parseExpressions(
															function( Expr )
															{
																				Expr.parseExpressionElements( function( ExprEl ){

																											 ExprEl.updateParamsByGaze();

																				} );
															}

			);


			if(  currentExprObj  )
			{

				var 	a = face.current.gaze.x - face.current.gaze._previous.x;
				var 	b = face.current.gaze.y - face.current.gaze._previous.y;

				var 	d 				= Math.sqrt( a*a + b*b );
				var	speed 		= currentExprObj.settings["gaze-speed"].value * currentExprObj.settings["gaze-speed"].multiplier;
				var	mult			=	10000;
				var	dur 			= (d/speed ) * mult;
				var	easing		=	currentExprObj.settings["gaze-speed"].easing;

					currentExprObj.parseExpressionElements(
						function( ExprEl )
						{
							if( !ExprEl.settings.static )
							{
								if( 		currentExprObj.settings[ "animation-effect" ].name &&
                	ExprEl.animationEffectModule[  currentExprObj.settings[ "animation-effect" ].name ] &&
                  Helpers.isInArray(ExprEl.name,ExprEl.animationEffectModule[  currentExprObj.settings[ "animation-effect" ].name ].elements) &&
                  ExprEl.animationEffectModule[  currentExprObj.settings[ "animation-effect" ].name ].enabled
								)
								{
									ExprEl.animate( currentExprObj.settings[ "animation-effect" ].name , null , null , null , { duration : dur , easing : easing	});
								}
								else{	ExprEl.animate("GoToDefault" , null , null , null , { duration : dur , easing : easing	});	}
							}
						}
					);
			}

 };



  Face.prototype._startAnimate 	= function()
 {
	var	face							= this;
	var	currentExprObj 			= face._getExpression( face.current.expression );

			if( currentExprObj.settings.animation.name  )
			{

					face._stopAllAnimate(	currentExprObj.settings.animation.name		);

					currentExprObj.parseExpressionElements( function( ExprEl ){

						if( !ExprEl.animationModule[ currentExprObj.settings.animation.name	 ].enabled )
						{
								console.log("animation "+currentExprObj.settings.animation.name +" is not enabled for this expression '"+currentExprObj.name +"'");
								return false;
						}
						ExprEl.animate( 		currentExprObj.settings.animation.name		, null , null , null , null 	);


					} );

			}

 };

 Face.prototype._stopAnimate 	= function()
 {

	var	face							= this;
	var	currentExprObj 			= face._getExpression( face.current.expression );

			if( currentExprObj.settings.animation.name )
			{
					currentExprObj.parseExpressionElements( function( ExprEl ){

												for( var m in ExprEl.animateInProgress )
												{
														ExprEl.animateInProgress[ m ] = false;
												}
					} );

			}

 };


   Face.prototype._renderer 	= function()
 {
		var	face	=	this;
		var	r		= {
							start	:	function()
							{
												var 	_t_ = Date.now();
												if( face.rendererIsRunning )
												{
														return true;
												}
												function updateFrames()
												{
													if( Date.now() - _t_ > 32 )
													{
															face.canvas.renderAll();
															_t_ = Date.now();
													}
													if( face.rendererIsRunning  )
													{
															face.rendererIsRunning	=	true;
															fabric.util.requestAnimFrame( updateFrames	,	 face.canvas );
													}
												}
												face.rendererIsRunning 	=	true;
												updateFrames();
							},
							stop	:	function()
							{
												face.rendererIsRunning	=	false;
							}
		};
		return r;
 };




  Face.prototype._stopAllAnimate 	= function(  exeption	 )
 {
	var	face	= this;
			this._parseExpressions(
												function( Expr )
												{
															Expr.parseExpressionElements( function( ExprEl )
															{
																					for( var m in ExprEl.animateInProgress )
																					{
																						if( exeption  )
																						{
																							if( m != exeption )
																							{
																								ExprEl.animateInProgress[ m ] = false;
																							}
																						}
																						else
																						{
																							ExprEl.animateInProgress[ m ] = false;
																						}
																					}
															});
												}
			);
 };

  /** This is the API for users  **/

Face.prototype.defineModel				= function( JsonObject )	// a valid well !~formatted~! JSON
{
		if( !Helpers.checkArgs(	"defineModel" , arguments , ["object"] ) ){ return false; }

		if( JsonObject.expressions  )
		{
			for(  var c in JsonObject.expressions   )
			{
					this.defineExpression( c , JsonObject.expressions[ c ] );
			}
		}

		if( JsonObject.synonyms  )
		{
			for(  var a = 0 ; a <  JsonObject.synonyms.length ; a++   )
			{
					this.addSynonyms( JsonObject.synonyms[ a ].expression 	,	JsonObject.synonyms[ a ].synonyms  	);
			}
		}

		if( JsonObject[ "one-shot-animations" ]  )
		{
			for(   var b in JsonObject["one-shot-animations"]    )
			{
					if(  AnimationModule.prototype[ b ]				&& 		b[ 0 ] !="_"	)
					{
							Helpers.extendLeft( 	AnimationModule.prototype[ b ] 	, JsonObject["one-shot-animations"][ b ]   );
					}
					else
					{
							console.log( "Error setting one-shot-animation with name : " + b +" . This animation name does not belong to animation supported list" );
					}
			}
		}

		if( JsonObject[ "continuous-animations" ]  )
		{
			for(   var z in JsonObject["continuous-animations"]    )
			{
					if(  AnimationModule.prototype[ z ]				&& 		z[ 0 ] !="_"	)
					{
							Helpers.extendLeft( 	AnimationModule.prototype[ z ] 	, JsonObject["continuous-animations"][ z ]   );
					}
					else
					{
							console.log( "Error setting continuous-animation with name : " + z +" . This animation name does not belong to animation supported list" );
					}
			}
		}

		if( JsonObject[ "animation-effects" ]  )
		{
			for(   var d in JsonObject["animation-effects"]    )
			{
					if(  AnimationEffectModule.prototype[ d ]		&& 		d[ 0 ] !="_"	)
					{
							Helpers.extendLeft( 	AnimationEffectModule.prototype[ d ] 	, JsonObject["animation-effects"][ d ]   );
					}
					else
					{
							console.log( "Error setting animation-effect with name : " + d +" . This animation name does not belong to animation supported list" );
					}
			}
		}
};


 Face.prototype.addSynonyms		= function( expressionName , arr )
{

		if( !Helpers.checkArgs( "addSynonyms" , arguments , ["string"] )  ){ return false; }

		var	synonymArray = [] ;
		var	Exp				=	this._getExpression( expressionName );
				if( !Exp )
				{	// expression does not exist
					return false;
				}

		function	uniq(a) {
				return a.sort().filter(function(item, pos, ary) {
							return !pos || item != ary[pos - 1];
				});
		}


		for( var m = 1 ; m < arguments.length ; m ++ )
		{
					if(	 !Helpers.isArray( arguments[ m ] )	)
					{
							if( !Helpers.checkArgs( "addSynonyms" , [ arguments[ m ] ] , ["string"] )  ){ return false; }

							synonymArray.push( arguments[ m ] );
					}
					else
					if(	 Helpers.isArray( arguments[ m ] , ["array"] )	)
					{
							if( !Helpers.checkArgs( "addSynonyms" , [ arguments[ m ] ] , ["arrayOfStrings"] )  ){ return false; }

							synonymArray	=	synonymArray.concat( arguments[ m ] );
					}

		}

		// check if synonym is an expression name.

		for( var ex = 0 ;  ex < this.expressions.length ; ex++ )
		{
			for( var syn = synonymArray.length - 1; syn >= 0;  syn-- )
			{
				if( this.expressions[ ex ].name ===  synonymArray[ syn ] &&  this.expressions[ ex ].name !== Exp.name )
				{
						return false;

				}
				if( this.expressions[ ex ].name ===  synonymArray[ syn ] &&  this.expressions[ ex ].name === Exp.name )
				{
						// remove from synonyms array if it contains same 'name' as 'expressionName'
						synonymArray.splice( era , 1 );
				}
			}
		}

		// find expression in face.synonyms and add more synonyms if exists. If does not exist, create an new entry
		var	hasSynonyms = false;
		for( var faSyn = 0 ; faSyn < this.synonyms.length ; faSyn++ )
		{
				if(   this.synonyms[ faSyn ].expressionName === Exp.name	)
				{
							this.synonyms[ faSyn ].expressionSynonyms 	= 	this.synonyms[ faSyn ].expressionSynonyms.concat( synonymArray );

							this.synonyms[ faSyn ].expressionSynonyms	=	uniq( this.synonyms[ faSyn ].expressionSynonyms );

							hasSynonyms = true;
							//break;
				}
				else
				{
							for( var det = 0; det < synonymArray.length ; det++ )
							{
									for( var era = this.synonyms[ faSyn ].expressionSynonyms.length - 1;  era >= 0;  era-- )
									{

											if( 	this.synonyms[ faSyn ].expressionSynonyms[ era ]=== synonymArray[ det ]	)
											{
															this.synonyms[ faSyn ].expressionSynonyms.splice( era , 1 );
											}

									}
							}
				}
		}
		if( hasSynonyms === false )
		{
				this.synonyms.push({ expressionName : Exp.name , expressionSynonyms : uniq( synonymArray ) });
		}

		return true;
};








Face.prototype.defineExpression 		= function( str , JsonObject )
{
		if( !Helpers.checkArgs( "defineExpression" , arguments , ["string","object"])  ){ return false; }

		var	face								= this;
				JsonObject.name 			= str;

		var 	m 			=	face._createExpression( JsonObject );
				if(	m	)  {
								face._addExpression(	m	);

								if( JsonObject["continuous-animation"] 	)
								{
										face.setAnimation(	JsonObject.name , JsonObject["continuous-animation"].name	,	JsonObject["continuous-animation"]	)	;
								}
								if(  JsonObject["one-shot-animation"]	)
								{
										face.setAnimation(	JsonObject.name , JsonObject["one-shot-animation"].name		,	JsonObject["one-shot-animation"]	)	;
								}
								if( JsonObject["animation-effect"] 	)
								{
										face.setAnimationEffect(	JsonObject.name , JsonObject["animation-effect"].name	,	JsonObject["animation-effect"]			)	;
								}
				}

};


Face.prototype.setExpression			= function( str ){

		var 	face 		= this;

		if( !Helpers.checkArgs( "setExpression" , arguments , ["string"] )   ){ return false; }

		var	Exp			=	this._getExpression( str );

		if( !Exp ){ console.log( "this expression name or a synonym : "+str+" has not been defined. use defineExpression to define a new expression");return false; }

		if( this.current.expression === Exp.name ){	return false;	}

		if( this.transitionIsRunning === true ){	console.log("another transition is in progress.Please wait to end");return false;	}

		this._switchExpression(  Exp.name  );

		this.current.expression = Exp.name;

		return true;

};


Face.prototype.setGazeDirection		= function( x , y ){

		if( !Helpers.checkArgs("setGazeDirection",arguments,["number","number"],[{Vmin:0,Vmax:1},{Vmin:0,Vmax:1}]) ){return false;}

		var 	face = this;
				face.current.gaze._previous.x = face.current.gaze.x;
				face.current.gaze._previous.y = face.current.gaze.y;
				face.current.gaze.x	=	x;
				face.current.gaze.y	=	1-y;

				face._switchGaze();

};


Face.prototype.unsetGazeDirection	= function(){

		var	face = this;
				face.current.gaze._previous.x = face.current.gaze.x;
				face.current.gaze._previous.y = face.current.gaze.y;
				face.current.gaze.x	=	face.settings.gaze.x;
				face.current.gaze.y	=	face.settings.gaze.y;

				face._switchGaze();
};


Face.prototype.setGazeSpeed				= function( exprStr , n , easyStr )
{
		if( !Helpers.checkArgs("setGazeSpeed",arguments,["string","number","string"],[false,false,["linear","ease-in","ease-out","ease-in-out"]]) 	)
		{
			return false;
		}
		var 	Exp		=	this._getExpression( exprStr ) ;
		var	match	=	{ "ease-in" : "easeInQuad"	,"ease-out" :	"easeOutQuad" ,	"ease-in-out"	: "easeInOutQuad" , "linear":"linear"} ;

		if( 	exprStr !=="*" 	&&  	!Exp 		){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }


		if( exprStr === "*" )
		{
				for( var k  = 0; k <  this.expressions.length; k++ )
				{
						this.expressions[ k ].settings[ "gaze-speed" ].multiplier = n;
						this.expressions[ k ].settings[ "gaze-speed" ].easing = match[ easyStr.toLowerCase()  ] ;
				}
		}
		else
		{
				Exp.settings[ "gaze-speed" ].multiplier = n;
				Exp.settings[ "gaze-speed" ].easing = match[ easyStr.toLowerCase()  ] ;

		}


	//	if( 	!Exp	){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }

	//	Exp[ "settings" ][ "gaze-speed" ] [ "multiplier" 	] = n;
	//	Exp[ "settings" ][ "gaze-speed" ] [ "easing" 		] = match[ easyStr.toLowerCase()  ] ;

		return true;
};



















Face.prototype.setAnimationEffect		= function( exprStr , effectName  , settings )
{

		if( !Helpers.checkArgs( "setAnimationEffect" , arguments , ["string","string","object"],[false,[ "bounce","splat"	,"road-runner","swoosh","jelly"],false] ) 	)
		{
			return false;
		}

		var 	Expression	=	this._getExpression( exprStr );

		if( exprStr !=="*" 	&&  !Expression 	){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }

		var errorMessage	=	"problem setting animation Effect "+effectName+" . Effect maybe is not a part of library effects";


		if( exprStr === "*" )
		{
			for( var k  = 0; k <  this.expressions.length; k++ )
			{
				this.expressions[ k ].settings["animation-effect"].name = effectName;

				MergeIt( this.expressions[ k ] , settings );
			}
		}
		else
		{
				Expression.settings["animation-effect"].name = effectName;

				MergeIt( Expression , settings );
		}

		function MergeIt( Expression , settings )
		{

				Expression.parseExpressionElements(
																	function( ExprEl ){

																			ExprEl.settings[ 	"animation-effect" 	].name = JSON.stringify( Expression.settings[ "animation-effect" ].name );

																			var	effectDefaults		=	ExprEl.animationEffectModule[		Expression.settings[ "animation-effect" ].name		];
																			var	copyDefaults		=	JSON.parse( 	JSON.stringify( effectDefaults )		);
																			ExprEl.animationEffectModule[		Expression.settings[ "animation-effect" ].name		]	=	copyDefaults;
																			Helpers.extendLeft( 	copyDefaults 	, settings   );

																	}
																);
		}



};

Face.prototype.unsetAnimationEffect	= function( exprStr  , removeSettings )
{
		if( !Helpers.checkArgs( "unsetAnimationEffect" 	, arguments , ["string"] ) 	)
		{
			return false;
		}
		var 	Expression	=	this._getExpression( exprStr );

		if( exprStr !=="*" 	&& 	!Expression 	){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }

		if( exprStr === "*" )
		{
			for( var k  = 0; k <  this.expressions.length; k++ )
			{
				resetParameters( this.expressions[ k ] , this.expressions[ k ].settings[	"animation-effect"	].name );

				this.expressions[ k ].settings[	"animation-effect"	].name	=	this.expressions[ k ].defaults[ "animation-effect" ].name 	;

				passToElements(	 this.expressions[ k ]  );

			}
		}
		else
		{
				resetParameters( Expression , Expression.settings[	"animation-effect"	].name );

				Expression.settings[	"animation-effect"	].name	=	Expression.defaults[ "animation-effect" ].name 	;

				passToElements(	 Expression  );
		}


		function passToElements(	 Expression	){

							Expression.parseExpressionElements(

									function( ExprEl ){

											ExprEl.settings[ 	"animation-effect" 	].name = 	Expression.defaults[ "animation-effect" ].name 	;

									}

							);

		}

		function resetParameters( Expression , effectName )
		{
							Expression.parseExpressionElements(
																				function( ExprEl )
																				{
																								if( ExprEl.animationEffectModule[ 		effectName	]	)
																								{

																										var		forces	=	ExprEl.animationEffectModule[ 	effectName+"_forces"	];
																													for( var b = 0; b < forces.length; b++ )
																													{
																															forces[ b ].STOP = true;

																													}

																													setTimeout(function(){
																															ExprEl.UI_elem.left		= ExprEl.params.left;
																															ExprEl.UI_elem.top		= ExprEl.params.top;
																															ExprEl.UI_elem.width	= ExprEl.params.width;
																															ExprEl.UI_elem.height	= ExprEl.params.height;
																															ExprEl.UI_elem.scaleX	= 1;
																															ExprEl.UI_elem.scaleY	= 1;
																															ExprEl.UI_elem.angle	= 0;
																															ExprEl.UI_elem.skewX	= 0;
																													},20);

																										if( 	removeSettings	)
																										{
																											delete	ExprEl.animationEffectModule[ 	effectName	];
																										}
																								}

																				}
																			);
		}



};















Face.prototype.setAnimation				= function( exprStr , animationName , settings ){

		if( !Helpers.checkArgs( "setAnimation" 	, arguments , ["string","string","object"] ,[false,[ "blinking","fluctuating"	,"fluctuating-upper","twitching-lower","tear-drop","snoozing","wink","widen"	,"eye-roll"],false] ) 	)
		{
			return false;
		}

		var 	Expression	=	this._getExpression( exprStr );

		if( exprStr !=="*" && 	!Expression 	){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }

		var errorMessage = "problem setting animation "+animationName+". Animation maybe is not a part of library continuous or one-shot animations";

		if( settings && settings.easing )
		{
			if( !Helpers.checkArgs(	"setAnimation"	,	[	settings.easing	],["string"]	,	[ ["linear","ease-in","ease-out","ease-in-out"] ] ) 	)
			{
				return false;
			}
			var	 	match				=	{ "ease-in" : "easeInQuad"	,"ease-out" :	"easeOutQuad" ,	"ease-in-out"	: "easeInOutQuad" , "linear":"linear"};
						settings.easing	= match[ settings.easing.toLowerCase()  ] ;
		}

		if( exprStr === "*" )
		{
			for( var k  = 0; k <  this.expressions.length; k++ )
			{
				this.expressions[ k ].settings.animation.name 	=  animationName;

				MergeIt( this.expressions[ k ] , settings );
			}
		}
		else
		{
				Expression.settings.animation.name 	= 	animationName;

				MergeIt( Expression , settings );

		}

		function MergeIt( Expression , settings )
		{

				Expression.parseExpressionElements(
																	function( ExprEl ){

																			ExprEl.settings.animation.name = Expression.settings.animation.name;

																			var	effectDefaults		=	ExprEl.animationModule[		Expression.settings.animation.name		];
																			var	copyDefaults		=	JSON.parse( 	JSON.stringify( effectDefaults )		);
																			ExprEl.animationModule[		Expression.settings.animation.name		]	=	copyDefaults;
																			Helpers.extendLeft( 	copyDefaults 	, settings   );

																	}
																);
		}

};

Face.prototype.unsetAnimation			= function( exprStr , removeSettings )
{
		if( !Helpers.checkArgs( "unsetAnimation" 	, arguments , ["string"] ) 	)
		{
			return false;
		}

		this._stopAnimate();

		var 	Expression	=	this._getExpression( exprStr );

		if( exprStr !=="*" && 	!Expression 	){ console.log( "this expression name : "+exprStr+" has not been defined. use defineExpression to define a new expression");return false; }
		if( exprStr === "*" )
		{
			for( var k  = 0; k <  this.expressions.length; k++ )
			{

				resetParameters( this.expressions[ k ] , this.expressions[ k ].settings.animation.name );

				this.expressions[ k ].settings.animation.name	=	this.expressions[ k ].defaults.animation.name ;

				passToElements(	 this.expressions[ k ]	);
			}
		}
		else
		{
				resetParameters( Expression , Expression.settings.animation.name );

				Expression.settings.animation.name	=	Expression.defaults.animation.name 	;

				passToElements(	 Expression	);
		}

		function resetParameters( Expression , animationName )
		{
							Expression.parseExpressionElements(
																				function( ExprEl )
																				{
																								if( removeSettings	&&	ExprEl.animationModule[ 		animationName	]	)
																								{
																										delete	ExprEl.animationModule[ 	animationName	];
																								}
																				}
																			);
		}

		function passToElements(	 Expression	){

							Expression.parseExpressionElements(

									function( ExprEl ){

											ExprEl.settings.animation.name = 	Expression.defaults.animation.name ;

									}

							);

		}



};



















Face.prototype.playAnimation				= function()
{
		this._startAnimate();
};

Face.prototype.stopAnimation				= function()
{
		this._stopAnimate();
};

 "use strict";

  function Expression(  constructorProperties ,  settings )
 {
		this.settings 					= null;
		this._Face						= "";
		this.name						= null;
		this.expressionElements	= [];

		Helpers.extend(	 	this		,		constructorProperties 	);

		 if( settings )
		{
			this.settings =	Helpers.extend( 	JSON.parse(	JSON.stringify( this.defaults ) 	)	, settings   );

		}else
		{
			this.settings =	JSON.parse( JSON.stringify( this.defaults ) );
		}

		this.init();

		return this;
 }

 Expression.prototype.defaults = {

	"elements"				: []		,
	"gaze-base"  			: 0.25	,
	"gaze-speed"			: {

						"multiplier"			: 1		,
						"value" 				: 20		,
						"easing"				: "linear"

	},
	"animation"			: {

						"name"				: 	""
	},
	"animation-effect"	: {

						"name"				:	""
	}

 };


 Expression.prototype.init			=	function()
 {
	var	expr	=this;
	var	elems =	this.settings.elements ,
			v;

			for( 	v  = 0; v <	elems.length; v++ )
			{
				(function( el ){

					expr.expressionElements.push( 	expr.createExpressionElement( el )		);

				})( elems[ v ] );
			}

			this.name = this.settings.name;
 };


 Expression.prototype.destroy		=	function()
 {
			this.parseExpressionElements(
												function( expressionElement )
												{
																expressionElement.destroy();
												}
			);
			this.expressionElements	=	[];
			var Ex =	this;
			Ex._Face._parseExpressions(function( expr , k ){

																if( expr === Ex ){

																			Ex._Face.expressions.splice( k , 1 );
																			return false;
																}
			});

 };



 Expression.prototype.draw			=	function()
 {
			this.parseExpressionElements(
														function( expressionElement )
														{
																expressionElement.draw();
														}
			);
 };


 Expression.prototype.clear		=	function()
 {
			this.parseExpressionElements(
														function( expressionElement )
														{
																expressionElement.clear();
														}
			);
 };


 Expression.prototype.createExpressionElement 	= function( props )
 {
	var	Expression	=	this,
			inherits		=	{
										"_Face" 			: Expression._Face	,
										"_Expression"	: Expression
			};

			return	new ExpressionElement( inherits	,	props );
 };



  Expression.prototype.getExpressionElement 		= function( name )
 {
	var	exEl = false;

			this.parseExpressionElements( 	function( el , index ){

																							if( el.name === name )
																							{
																								exEl	=	 el;
																								return false;
																							}

														} );
	return	exEl;
 };


 Expression.prototype.parseExpressionElements	 	= function( callback  )
 {
			if( !callback ){ return false; }

	var	els 	= 	this.expressionElements ,
			len	=	els.length,
			m		=	0,
			cal	= 	null;

			for(	var m = els.length - 1; m >= 0; m-- )
			{
				cal	=	callback( els[ m ] , m );
				if( cal	===	false ){	break;	}
			}

			return cal;
 };

 "use strict";

 function ExpressionElement( constructorProperties , settings )
 {
		var SELF = this;

		this.settings 		= "";
		this.name			= null;
		this.UI_elem		= null;
		this._Face			= "";
		this._Expression 	= "";
		this.params		= {

				left		: null,
				top		: null,
				width		: null,
				height	: null,
				opacity	: null
		};
		this.to_params	= {

				left		: null,
				top		: null,
				width		: null,
				height	: null,
				opacity	: null
		};
		this.isLoading  				= false;
		this.forceStop					= false;		//	used also in  	forceStop
		this._onload					= false;

		this.forceStopProgress		= {};		// used also in  animationModule.js
		this.animateInProgress 	= {};		// used also in 	main.js   and  animationModule.js


		Helpers.extend( 		this			,		constructorProperties 	);

		 if( settings )
		{
			SELF.settings =	Helpers.extend( JSON.parse(	JSON.stringify( this.defaults ) 	) , settings  );

		}else
		{
			SELF.settings =	JSON.parse( JSON.stringify( this.defaults ) );
		}

		if( typeof AnimationModule != 'undefined'		)
		{
					this.animationModule 			=	new AnimationModule();
		}else
		{
					this.animationModule 			=	false;
		}

		if( typeof AnimationEffectModule != 'undefined'		 )
		{
					this.animationEffectModule 	=	new AnimationEffectModule();
		}else
		{
					this.animationEffectModule 	=	false;
		}

		SELF.init();




		return this;
 }


 ExpressionElement.prototype.defaults = {

	"name"			: ""		,
	"static"			: true	,
	"resizeBase"	: 1284	,
	"image" 	 	: null		,
	"pupil_x"	 	: null		,
	"pupil_y"	 	: null		,
	"animation"	: {

						"name"				: 	""
	},
	"animation-effect"	: {

						"name"				:	""
	}
 };



 ExpressionElement.prototype.init 				= function()
 {

 		var	ExprElem 				=	this							,
				settings					= 	ExprElem.settings	,
				imgPath					=	settings.image	;

				ExprElem.name	=	settings.name			;

		if( imgPath	 ){


				fabric.Image.fromURL( imgPath , function( img ) {

						if( settings.resizeBase	)
						{
								img.width  					= Helpers.resizeBasedOn(	ExprElem._Face.settings.face_width	,	settings.resizeBase , img.width				);
								img.height 				= Helpers.resizeBasedOn(	ExprElem._Face.settings.face_width	,	settings.resizeBase , img.height			);
								settings._pupil_x 	= Helpers.resizeBasedOn(	ExprElem._Face.settings.face_width	,	settings.resizeBase , settings.pupil_x	);
								settings._pupil_y 	= Helpers.resizeBasedOn(	ExprElem._Face.settings.face_width	,	settings.resizeBase , settings.pupil_y	);

						}else
						{
								img.width  					= 	img.width;
								img.height 				= 	img.height;
								settings._pupil_x 	=	settings.pupil_x;
								settings._pupil_y 	=	settings.pupil_y;
						}
						ExprElem.params.left		= ExprElem._Face.settings.face_width	/	2;
						ExprElem.params.top		= ExprElem._Face.settings.face_height	/	2;
						ExprElem.params.width	= img.width;
						ExprElem.params.height	= img.height;

						ExprElem.UI_elem = img;

						img.set(
									{	opacity	:	0				,
										originX	:	"center"		,
										originY	:	"center"
									}
						);

						ExprElem.updateParamsByGaze();

						ExprElem.isLoading = false;

						if( ExprElem._onload )
						{
								ExprElem._onload( ExprElem );
						}

						//var sss = Math.floor(Math.random() * 9)*1000 + 1;
						//setTimeout(function(){





						for( var j  = 0 ; j < ExprElem._Face.loadingComponents.length; j++ )
						{
								if( ExprElem._Face.loadingComponents[ j ] === ExprElem )
								{

										ExprElem._Face.loadingComponents.splice( j , 1 );
								}
						}
						if(		ExprElem._Face.loadingComponents.length	=== 0 	&& 	ExprElem._Face.hasOwnProperty("onload")		)
						{
										ExprElem._Face.onload(	ExprElem._Face	);
						}




						//},sss);




				});


		ExprElem.isLoading = true;

		ExprElem._Face.loadingComponents.push( ExprElem );

		}

 };


 ExpressionElement.prototype.destroy 						= function()
 {
		var 	ExprElm = this;

		this.clear();
		this.forceStop = true;
		for( var u in this.forceStopProgress )
		{
				 this.forceStopProgress[ u ] = true;
		}
		for( var u in this.animateInProgress )
		{
				 this.animateInProgress[ u ] = false;
		}
		this.UI_elem = null;
		this._Expression.parseExpressionElements(

					function(el,k){
											if( el === ExprElm )
											{
												ExprElm._Expression.expressionElements.splice( k , 1 );
											}
					}

		);
 };


 ExpressionElement.prototype.draw 							= function()
 {
  		var 	t 	= 	this.params.top,
				l	= 	this.params.left,
				w	=	this.params.width,
				h	=	this.params.height,
				o	=	this.params.opacity;

		this.UI_elem.set(
									{
										left 		: l 	,
										top 		: t 	,
										width 	: w 	,
										height 	: h 	,
										opacity 	: o
									}
		);

		this._Face.canvas.add( this.UI_elem );

		if( this.name === "background" ||  this.name === "face-background" )
		{
			this._Face.canvas.sendToBack(	this.UI_elem	);
		}

 };


 ExpressionElement.prototype.clear						= function()
 {
		this.UI_elem.remove();
 };


 ExpressionElement.prototype.updateParamsByGaze 	= function()
 {

 	var	ExprElem 	=	this							,
			face = ExprElem._Face			,
			Expression	=	ExprElem._Expression	,
			gaze			=	face.current.gaze		,
			XPUPIL											,
			YPUPIL											;

		if ( ExprElem.settings.hasOwnProperty("static") && ExprElem.settings.static === true  )
		{
				return	false;
		}

		if ( ExprElem.name.toLowerCase() === "left-eye" )
		{
				XPUPIL 		= gaze.x 	- 	Expression.settings["gaze-base"]/2;
		}
		else
		if ( ExprElem.name.toLowerCase() === "right-eye" )
		{
				XPUPIL		= gaze.x 	+ 	Expression.settings["gaze-base"]/2;
		}

		YPUPIL				= gaze.y;

		ExprElem.params.left	=  face.canvas.width	 *  XPUPIL  + ExprElem.params.width	/2  	- 	ExprElem.settings._pupil_x;
		ExprElem.params.top	=  face.canvas.height	 *  YPUPIL  + ExprElem.params.height	/2 	- 	ExprElem.settings._pupil_y;


 };


 ExpressionElement.prototype.animate 					= function( animationName , properties , animationSettings , startAfter , callbacks )
 {

			if( !fabric.util.ease.linear )
			{
					fabric.util.ease.linear = function(t, b, c, d) { return c*t/d + b; };
			}

 	var	ExprElem 			=	this;

	var	DefaultCallbacks	=	{

				"duration" 		: 	1000,
				"abort"			:	 function(){
															return ExprElem.forceStop;
				},
				"onComplete"	:	function(){	ExprElem.isAnimating = false;	},
				"delayOnEnd"	:	0,
				"easing"			:	false																											//easeInQuad		easeOutQuad		easeInOutQuad
			};

			if( callbacks )
			{

					DefaultCallbacks.duration				=	callbacks.duration 	|| 	1000;
					if(	callbacks.onChange	)
					{
						DefaultCallbacks.onChange			=	callbacks.onChange;		// if set callbacks.onChange , it should be   false.
					}
					DefaultCallbacks.easing					=	fabric.util.ease[ callbacks.easing ]	 	||	false;
					if(	callbacks.onComplete	)
					{
						DefaultCallbacks.onComplete		=	function(){	ExprElem.isAnimating = false;  callbacks.onComplete();	};
					}
			}

																		ExprElem._Face._renderer().start();	// !!!!! start !

	switch ( animationName ) {

		case "GoToTarget"			:

														ExprElem.UI_elem.animate( properties ,	DefaultCallbacks );
			break;
		case "GoToDefault"			:
												var 	t 	= 	ExprElem.params.top,
														l	= 	ExprElem.params.left,
														w	=	ExprElem.params.width,
														h	=	ExprElem.params.height,
														o	=	ExprElem.params.opacity;

														ExprElem.UI_elem.animate(
																									{
																										left 		: l 	,
																										top 		: t 	,
																										width 	: w 	,
																										height 	: h 	,
																										opacity	: o
																									} ,
																									DefaultCallbacks
																		);

			break;
		/**
							Animations Here
		**/
		case "blinking" 				:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"blinking"				,	ExprElem	);	}
			break;
		case "fluctuating" 			:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"fluctuating"			,	ExprElem	);	}
			break;
		case "fluctuating-upper" 	:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"fluctuating-upper"	,	ExprElem	);	}
			break;
		case "twitching-lower"		:
													if( ExprElem.animationModule			){	ExprElem.animationModule._animationRunner(	"twitching-lower"		,	ExprElem	);	}
			break;
		case "tear-drop" 			:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"tear-drop"				,	ExprElem	);	}
			break;
		case "snoozing"				:
													if( ExprElem.animationModule			){	ExprElem.animationModule._animationRunner(	"snoozing"				,	ExprElem	);	}
			break;
		case "wink"					:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"wink"					,	ExprElem	);	}
			break;
		case "widen" 					:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"widen"					,	ExprElem	);	}
			break;
		case "eye-roll" 				:
													if( ExprElem.animationModule 			){	ExprElem.animationModule._animationRunner(	"eye-roll"				,	ExprElem	);	}
			break;
		/**
							Animation Effects Here
		**/
		case "bounce" 				:
													if( ExprElem.animationEffectModule 	){	ExprElem.animationEffectModule._animationRunner(	"bounce"		,	ExprElem	);	}
			break;
		case "jelly" 					:
													if( ExprElem.animationEffectModule 	){	ExprElem.animationEffectModule._animationRunner(	"jelly"			,	ExprElem	);	}
			break;
		case "splat" 					:
													if( ExprElem.animationEffectModule 	){	ExprElem.animationEffectModule._animationRunner(	"splat"			,	ExprElem	);	}
			break;
		case "swoosh" 				:
													if( ExprElem.animationEffectModule 	){	ExprElem.animationEffectModule._animationRunner(	"swoosh"		,	ExprElem	);	}
			break;
		case "road-runner" 			:
													if( ExprElem.animationEffectModule 	){	ExprElem.animationEffectModule._animationRunner(	"road-runner"	,	ExprElem	);	}
			break;
	}


 };
